package com.hrms.attendance.service;

import com.hrms.assignment.dto.AssignmentResponse;import com.hrms.assignment.service.AssignmentService;import com.hrms.attendance.model.ShiftSnapshot;import com.hrms.attendance.model.OfficeSnapshot;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.exceptions.*;import com.hrms.common.utils.CompanyTimeProvider;import com.hrms.config.AttendanceProperties;import com.hrms.office.model.OfficeLocation;import com.hrms.office.repository.OfficeLocationRepository;import com.hrms.shift.model.Shift;import com.hrms.shift.model.ShiftStatus;import com.hrms.shift.repository.ShiftRepository;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class AttendanceScheduleService {
 private final AssignmentService assignments;private final ShiftRepository shifts;private final OfficeLocationRepository offices;private final CompanyTimeProvider time;private final AttendanceProperties properties;private final ZoneId zone;
 public AttendanceScheduleService(AssignmentService a,ShiftRepository s,OfficeLocationRepository o,CompanyTimeProvider t,AttendanceProperties p,ZoneId z){assignments=a;shifts=s;offices=o;time=t;properties=p;zone=z;}
 public Schedule resolveCheckIn(String employeeId){Instant now=time.now();LocalDate today=time.companyDate();for(LocalDate candidate:List.of(today,today.minusDays(1))){try{AssignmentResponse a=assignments.resolve(employeeId,candidate);Schedule schedule=load(candidate,a);if(!now.isBefore(schedule.start().minus(Duration.ofMinutes(properties.earlyCheckInMinutes())))&&!now.isAfter(schedule.end().plus(Duration.ofMinutes(windowGrace(schedule)))) )return schedule;}catch(ApiException ignored){}}throw new ApiException(ErrorCode.NO_WORK_ASSIGNMENT,org.springframework.http.HttpStatus.CONFLICT,"No valid work assignment or attendance window applies now");}
 public Schedule load(LocalDate date,AssignmentResponse assignment){Shift s=shifts.findById(assignment.shiftId()).orElseThrow(()->new ApiException(ErrorCode.NO_WORK_ASSIGNMENT,org.springframework.http.HttpStatus.CONFLICT,"Assigned shift was not found"));OfficeLocation o=offices.findById(assignment.officeLocationId()).orElseThrow(()->new ApiException(ErrorCode.NO_WORK_ASSIGNMENT,org.springframework.http.HttpStatus.CONFLICT,"Assigned office was not found"));if(s.getStatus()!=ShiftStatus.ACTIVE||o.getStatus()!=com.hrms.office.model.OfficeStatus.ACTIVE)throw new ApiException(ErrorCode.NO_WORK_ASSIGNMENT,org.springframework.http.HttpStatus.CONFLICT,"Assigned shift or office is inactive");Instant start=date.atTime(s.getStartTime()).atZone(zone).toInstant();LocalDate endDate=s.getEndTime().isAfter(s.getStartTime())?date:date.plusDays(1);Instant end=endDate.atTime(s.getEndTime()).atZone(zone).toInstant();ShiftSnapshot ss=new ShiftSnapshot();ss.setShiftId(s.getId());ss.setShiftCode(s.getShiftCode());ss.setShiftName(s.getName());ss.setStartTime(s.getStartTime());ss.setEndTime(s.getEndTime());ss.setWorkingDays(s.getWorkingDays());ss.setGracePeriodMinutes(s.getGracePeriodMinutes());ss.setEarlyDepartureGraceMinutes(s.getEarlyDepartureGraceMinutes());ss.setExpectedBreakMinutes(s.getExpectedBreakMinutes());ss.setFlexible(s.isFlexible());ss.setScheduledStartAt(start);ss.setScheduledEndAt(end);OfficeSnapshot os=new OfficeSnapshot();os.setOfficeLocationId(o.getId());os.setLocationCode(o.getLocationCode());os.setName(o.getName());os.setCoordinates(o.getCoordinates());os.setGeofenceRadiusMeters(o.getGeofenceRadiusMeters());os.setMaximumGpsAccuracyMeters(o.getMaximumGpsAccuracyMeters());os.setAddressLine1(o.getAddressLine1());os.setAddressLine2(o.getAddressLine2());os.setCity(o.getCity());os.setState(o.getState());os.setPostalCode(o.getPostalCode());os.setCountry(o.getCountry());return new Schedule(date,assignment,ss,os,start,end);}
 private long windowGrace(Schedule schedule){return schedule.shift().getEndTime().isAfter(schedule.shift().getStartTime())?properties.lateCheckInWindowMinutes():Math.max(properties.lateCheckInWindowMinutes(),properties.overnightCheckoutGraceMinutes());}
 public record Schedule(LocalDate workDate,AssignmentResponse assignment,ShiftSnapshot shift,OfficeSnapshot office,Instant start,Instant end){}
}
